# Free-schedule (fs) ProVerif group: serial, outside the parallel roster, run by the full
# verification recipe, and free of axiom, restriction and elimtrue declarations. The
# transcript-fidelity test checks the complete wiring and the declaration allowlist.
require_line_count 1 '^check-proverif-fs: check-proverif-transcript-fidelity$' Makefile \
	"serial fs ProVerif group"
require_line_count 1 '^\t\+\$\(MAKE\) --no-print-directory -j1 \$\(PROVERIF_FS_CHECK_TARGETS\)$' Makefile \
	"serial fs ProVerif group recipe"
require_line_count 1 '^PROVERIF_FS_TIMEOUT \?= 1800$' Makefile "fs per-target timeout"
require_line_count 1 '^check-proverif-fs-records-s2b: check-proverif-extraction check-proverif-transcript-fidelity$' \
	Makefile "fs-records-s2b runner"
require_line_count 1 '^\tfs-records-s2b \\$' Makefile "fs-records-s2b in the serial fs roster"
require_line_count 1 '^check-proverif-fs-records-b2s: check-proverif-extraction check-proverif-transcript-fidelity$' \
	Makefile "fs-records-b2s runner"
require_line_count 1 '^\tfs-records-b2s$' Makefile "fs-records-b2s in the serial fs roster"
require_line_count 1 '^\tpython3 \$\(PROVERIF_DIR\)/test-pin-origin-checker\.py$' Makefile "pin-origin gate regression checks"
require_line_count 1 '^\tpython3 \$\(PROVERIF_DIR\)/pin-origin-theory\.py --check-only$' Makefile "pin-origin finite syntax gate"
python3 proofs/pro-verif/pin-origin-theory.py --check-only

# Complete local symbolic name-order argument, separate from computational draws.
require_line_count 2 '^\tpython3 \$\(PROVERIF_DIR\)/test-symbolic-name-order\.py$' Makefile "symbolic name-order regression gates"
require_line_count 2 '^\tpython3 \$\(PROVERIF_DIR\)/symbolic-name-order\.py --check-only$' Makefile "symbolic name-order finite gates"
python3 proofs/pro-verif/symbolic-name-order.py --check-only
require_line_count 0 '^check-proverif:.*fs' Makefile "fs group outside the parallel roster"
awk '
	/^verify-in-shell:/ { active = 1; next }
	active && /^[^[:space:]#]/ { active = 0 }
	active && $0 == "\t$(MAKE) check-proverif-fs" { found = 1 }
	END { exit !found }
' Makefile || fail "verify-in-shell must invoke check-proverif-fs"
reject_matches "ProVerif axiom, restriction or elimtrue declaration" \
	'(?m)^\s*(?:axiom|restriction|elimtrue)\b' "${handwritten_proverif[@]}" "$generated_proverif"

# Audit F16: the full verification recipe must finish by checking the reviewed boundary.
awk '
	/^verify-in-shell:/ { active = 1; next }
	active && /^[^[:space:]#]/ { active = 0 }
	active && $0 == "\t$(MAKE) check-inventory" { found = 1 }
	END { exit !found }
' Makefile || fail "verify-in-shell must invoke check-inventory"

