# Arbitrary registration admission/response are additional exact-result gates.
for registration_scenario in registration-set-admission registration-set-response registration-beacon-admission; do
	require_line_count 1 "^[[:space:]]+${registration_scenario} "'\\$' Makefile "${registration_scenario} aggregate scenario"
	require_line_count 1 "^check-proverif-${registration_scenario}: check-proverif-extraction$" Makefile "${registration_scenario} focused gate"
	require_line_count 1 "^            target: check-generated-proverif-${registration_scenario}$" ../.github/workflows/formal-verification.yml "${registration_scenario} CI gate"
done
for registration_checker in registration-set registration-response registration-beacon; do
	require_line_count 1 "^[[:space:]]+python3 .*test-${registration_checker}-checker.py$" Makefile "${registration_checker} checker regressions"
	require_line_count 1 "^[[:space:]]+python3 .*check-${registration_checker}.py --proverif .* --timeout .*" Makefile "${registration_checker} exact-result runner"
done
require_line_count 4 '^query ' proofs/pro-verif/registration-set-admission-queries.pvl "arbitrary admission correspondences"
require_line_count 8 '^query ' proofs/pro-verif/registration-set-response-queries.pvl "arbitrary response correspondences"
require_line_count 1 '^set maxHyp = 2\.$' proofs/pro-verif/registration-set-response-queries.pvl "sound Horn overapproximation setting"
require_line_count 9 '^query ' proofs/pro-verif/registration-beacon-admission-queries.pvl "Beacon admission correspondences and explicit unknown"
require_line_count 8 '^query ' proofs/pro-verif/registration-beacon-control-queries.pvl "Beacon admission concrete controls"

